def div_even_odd(numbers):
    """
    Computes the division of the first even number by the first odd number in the list.
    Raises a ValueError if:
      - there is no even number in the list
      - there is no odd number in the list
    """
    first_even = None
    first_odd = None

    for num in numbers:
        if first_even is None and num % 2 == 0:
            first_even = num
        if first_odd is None and num % 2 == 1:
            first_odd = num
        if first_even is not None and first_odd is not None:
            break

    if first_even is None:
        raise ValueError("Input must contain at least one even number.")
    if first_odd is None:
        raise ValueError("Input must contain at least one odd number.")

    return first_even / first_odd


