def find_Min_Diff(arr):
    if len(arr) < 2:
        return 0  # or raise an exception if less than two elements

    arr.sort()
    min_diff = float('inf')
    for i in range(1, len(arr)):
        diff = arr[i] - arr[i-1]
        if diff < min_diff:
            min_diff = diff
    return min_diff

